from time import *
from physical import *
from gpio import *
from pyjs import *


# cl-sensor-motion.js
class  SensorMotion:
    def __init__(self):        # var SensorMotion
        self.motionPrev = 0
        self.motion = 0
        self.devices = {}

        # init
        self.update_visuals()


    def update(self, sensors, devices):
        self.update_motion(sensors, devices)
        self.update_visuals()


    def valueDirection(self):
        if self.motionPrev is self.motion:
            return 0
        elif self.motionPrev < self.motion:
            return 1
        return -1


    def value(self):
        if self.motion:
            return self.motion
        elif self.valueDirection() is not 0:
            return 1
        return 0


    # private
    def update_visuals(self):
        # value
        value = self.value()        # var value
        if value > 0:
            setComponentOpacity("SensorMotionOn", 1)
            setComponentOpacity("SensorMotionOff", 0)
        else:
            setComponentOpacity("SensorMotionOn", 0)
            setComponentOpacity("SensorMotionOff", 1)



    # private
    def update_motion(self, sensors, devices):
        myname = getName()        # var myname

        self.motionPrev = self.motion

        for n in self.devices:        # var n
            self.devices[n].current = False


        for i, (k,v) in enumerate(devices.items()) :
            name = devices[k]        # var name
            mydev = self.devices.get(name)
            if name is myname:
                continue
            if mydev is None:
                self.devices[name] = JsObject({
                    "current": True
                })

                self.motion += 1
            else:
                mydev.current = True



        for nn in self.devices.copy():        # var nn
            if not self.devices[nn].current:
                del self.devices[nn]
                self.motion -= 1

var Timer = function() {
    this.started = (new Date()).getTime();    
}

Timer.prototype.elapsed = function(){
    return (new Date()).getTime() - this.started;
}

var DELAY = 200;
var SIZE = {width: 150, height: 150}; // largest component size 
var SERVER_PORT = 1234;
var SERVER_IP = "192.168.0.100";

var socket = null;
var sensors = {};
var count = 0;


function setup() {
	IoEClient.setup({
		type: "Street Lamp",
		states: [{
			name: "Light",
			type: "number",
			controllable: false
		}, {
			name: "Light gradient",
			type: "options",
			options: {
				"-1": "Decreasing",
				"0": "No Change",
				"1": "Increasing"
			},
			controllable: false
		}, {
			name: "Motion",
			type: "number",
			controllable: false
		}, {
			name: "Moton gradient",
			type: "options",
			options: {
				"-1": "Decreasing",
				"0": "No Change",
				"1": "Increasing"
			},
			controllable: false
		}]
	});

	sensors.light = new SensorLight();
	sensors.motion = new SensorMotion();

	socket = new UDPSocket();
	socket.begin(SERVER_PORT);
}

function loop() {
	var t = new Timer();

    var xpos = getX(),
        ypos = getY();
    var devices = devicesAt(xpos, ypos, SIZE.width, SIZE.height*2);

	t = new Timer();

	sensors.light.update(sensors, devices);
	sensors.motion.update(sensors, devices);

	// send data to the server
	var data = "";

	data += "streetlamp," + getSerialNumber() + "^";
	data += "light," + sensors.light.value() + "," + sensors.light.valueDirection() + "^";
	data += "motion," + sensors.motion.value() + "," + sensors.motion.valueDirection();

	socket.send(SERVER_IP, SERVER_PORT, data);
	sendReport();
	delay(DELAY);
}

function sendReport() {
	var report = sensors.light.value() + "," + sensors.light.valueDirection() + ","
		+ sensors.motion.value() + "," + sensors.motion.valueDirection();
	IoEClient.reportStates(report);
}

// cl-sensor-light.js
// Env.Sunlight is assumed to be from 0 to 100%

var SensorLight = function () {
    this.eLightMin = 0;     
    this.eLightMax = 100; // this is %, per Environment semantics for sunlight
    this.eLightMinValueOn = this.eLightMin+(this.eLightMax-this.eLightMin) / 3;

    // init
    setComponentOpacity("SensorLightOff", 0); 
    setComponentOpacity("SensorLightOn", 0); 
    setComponentOpacity("SensorLight", 0); 

    this.elight = Environment.get("Sunlight");
    this.sync_to_env();
    this.update_visuals();
};

SensorLight.prototype.update = function (sensors, devices) {
    this.sync_to_env();
    this.update_visuals();
};

SensorLight.prototype.valueDirection = function () {
    if(this.elightPrev === this.elight)
        return 0;
    else if(this.elightPrev < this.elight)
        return 1;
    return -1;
};

SensorLight.prototype.value = function () {
    return this.elight;
};

// private 
SensorLight.prototype.update_visuals = function () {
    // value
    var opacity = 0,
        value = this.value();
    if(value < this.eLightMinValueOn) {
        opacity = 1 - (value - this.eLightMin)/(this.eLightMinValueOn - this.eLightMin);
        setComponentOpacity("SensorLightOn", 1); 
        setComponentOpacity("SensorLightOff", 0); 
    }
    else{
        setComponentOpacity("SensorLightOn", 0); 
        setComponentOpacity("SensorLightOff", 1); 
    }
    setComponentOpacity("SensorLightLevel", opacity); 
};

// private 
SensorLight.prototype.sync_to_env = function (){
    this.elightPrev = this.elight;
    this.elight = Environment.get("Sunlight");
    if(this.elight < this.eLightMin)
        this.elight = this.eLightMin;
    if(this.elight > this.eLightMax)
        this.elight = this.eLightMax;
};

// cl-sensor-motion.js

var SensorMotion= function () {
    this.motionPrev = 0;
    this.motion = 0;
    this.devices = {};

    // init
    this.update_visuals();
};

SensorMotion.prototype.update = function (sensors, devices) {
    this.update_motion(sensors, devices);
    this.update_visuals();
};

SensorMotion.prototype.valueDirection = function () {
    if(this.motionPrev === this.motion)
        return 0;
    else if(this.motionPrev < this.motion)
        return 1;
    return -1;
};

SensorMotion.prototype.value = function () {
    if(this.motion)
    	return this.motion;
    else if(this.valueDirection() !== 0)
    	return 1;
    return 0;
};

// private 
SensorMotion.prototype.update_visuals = function () {
    // value
    var value = this.value();
    if(value > 0) {
        setComponentOpacity("SensorMotionOn", 1); 
        setComponentOpacity("SensorMotionOff", 0); 
    }
    else{
        setComponentOpacity("SensorMotionOn", 0); 
        setComponentOpacity("SensorMotionOff", 1); 
    }
};

// private 
SensorMotion.prototype.update_motion = function (sensors, devices) {
    var myname = getName();

	this.motionPrev = this.motion;

    for(var n in this.devices) {
        this.devices[n].current = false; 
    }

    for(var i=0; i<devices.length; ++i) {
        var name = devices[i],
            mydev = this.devices[name];
        if(name === myname)
            continue; 
        if(mydev === undefined){
            this.devices[name] = {current: true};
            ++this.motion;
        }
        else {
            mydev.current = true;
        }
    }

    for(var nn in this.devices){ 
        if(!this.devices[nn].current) {
            delete this.devices[nn];
            --this.motion;
      }
    }
};

var Timer = function() {
    this.started = (new Date()).getTime();    
}

Timer.prototype.elapsed = function(){
    return (new Date()).getTime() - this.started;
}

